('6af28b7d-3795-4e06-86d3-0b4ca2c8c193','MA','a00b00b0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Agadir Adventure Club SARL','Agadir Adventure Club','activity',2,'verified',ARRAY['en','fr','ar'],'A local outdoor club offering hiking, cycling, and climbing for all levels. Certified guides, quality equipment, and a passion for sharing Morocco''s natural beauty.',5.6,89.6,343,4.8,'active'),
('a0a372d0-9737-4a0d-8432-5be7e9784a83','MA','a00b00b0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Extreme Sports SARL','Atlas Extreme Sports','activity',3,'verified',ARRAY['en','fr','de'],'Adrenaline specialists — quad biking, sandboarding, paragliding, and canyoning. Professional instructors, top safety record, and GoPro footage included.',8.3,91.6,283,3.9,'active'),
('9fe08201-491e-452e-8526-247045b65da8','MA','a00b00b0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Sahara Wellness Retreat SARL','Sahara Wellness Retreat','activity',3,'verified',ARRAY['en','fr'],'A wellness sanctuary offering hammam, massage, yoga, and meditation sessions. Organic argan oil treatments and sound healing in a tranquil garden setting.',1.4,91.6,129,4.5,'active'),
('bd198a17-17c8-404b-b033-b665e894f293','MA','a00b00b0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Agadir Shuttle Express SARL','Agadir Shuttle Express','transfer',1,'verified',ARRAY['en','fr'],'Affordable shared shuttle service between the airport, train stations, and city hotels. Fixed schedules, comfortable minibuses, and friendly drivers.',8.5,94.5,387,3.7,'active'),
('d0cc37a5-9e23-4fec-be67-10cece51e66a','MA','a00b00b0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Private Transfers SARL','Atlas Private Transfers','transfer',3,'verified',ARRAY['en','fr','ar'],'Private door-to-door transfers with professional drivers and modern sedan cars. Flight tracking, meet-and-greet at the airport, and 24/7 availability.',5.6,99,426,4.7,'active'),
('5a950645-10d6-4b28-b368-27b54f0f7dd9','MA','a00b00b0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Chauffeur Morocco SARL','Royal Chauffeur Morocco','transfer',4,'verified',ARRAY['en','fr','es'],'Luxury chauffeur service with Mercedes E-Class and V-Class vehicles. Leather interiors, bottled water, phone chargers, and English-speaking drivers in suits.',0.6,91.8,171,5,'active'),
('07525b70-56ff-417b-826e-c922eb207450','MA','a7777777-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Meknès Heritage Walks SARL','Meknès Heritage Walks','tour',2,'verified',ARRAY['en','fr','ary-Latn'],'A family-run walking tour company founded in 2009. We specialize in intimate small-group tours of historic quarters, led by licensed local guides who grew up in these streets.',5.4,95.9,98,4.7,'active'),
('0868a429-9354-40f6-85bd-9202e3234090','MA','a7777777-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Cultural Tours SARL','Atlas Cultural Tours','tour',3,'verified',ARRAY['en','fr','de'],'Mid-size cultural tour operator with air-conditioned minibuses and university-trained historians. We cover major landmarks with comfortable logistics.',11.4,97.2,244,3.6,'active'),
('142b0642-95b8-420a-92d0-99492da6876b','MA','a7777777-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Concierge Meknès SARL','Royal Concierge Meknès','tour',4,'verified',ARRAY['en','fr','es','it'],'Private luxury touring service with Mercedes vans, art-historian guides, and exclusive access to private palaces and collections not open to the public.',10.9,93,169,4.5,'active'),
('128d17ae-499a-48f6-8ede-adc4561f38e4','MA','a7777777-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Local Eyes Meknès SARL','Local Eyes Meknès','guided_experience',1,'verified',ARRAY['en','fr','ary-Latn'],'A collective of young local guides who show you the real city — hidden cafes, street art, and neighborhoods the guidebooks miss. Pay-what-you-want ethos.',0.8,94.5,137,4.4,'active'),
('867067b6-184d-4dfd-a2d0-421c1453f2b9','MA','a7777777-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Insider Morocco SARL','Insider Morocco','guided_experience',3,'verified',ARRAY['en','fr','ar'],'Boutique guiding company pairing you with a dedicated guide for a personalized half-day or full-day experience. We adapt the route to your interests on the fly.',2.2,92.3,359,4.2,'active'),
('36270429-e7fd-4f52-a9da-c37a76f3ee84','MA','a7777777-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Kasbah Storytellers SARL','Kasbah Storytellers','guided_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'Cultural preservation association. Our guides are retired teachers and historians who share oral traditions, folklore, and stories passed down for generations.',8.2,94.1,278,3.6,'active'),
('b9406fd0-9d7c-41e7-b757-33df072f4f9a','MA','a7777777-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Meknès Cooking School SARL','Dar Meknès Cooking School','workshop',2,'verified',ARRAY['en','fr','ary-Latn'],'A traditional riad kitchen where a local family teaches you to prepare tagine, couscous, and pastries from scratch. Small classes, maximum 6 people.',7.3,92.7,73,3.7,'active'),
